section.code:
/* Adaptive Framework configuration. */
[
    // Adapter holding configuration objects.
    {
        type           : "adapter",
        adapterId      : "conf",
        adapterType    : "file",
        contentType    : "json",
        filenameSuffix : ".json",
        root           : "/var/lib/afw/config/"
    },

    // Serve every URI through the adapter request handler.
    {
        type               : "requestHandler",
        uriPrefix          : "/",
        requestHandlerType : "adapter"
    },

    {
        type          : "application",
        applicationId : "MyApplication",
        title         : "My Application",
        confAdapterId : "conf"
    }
]
